template <typename T>
void rTbl2<T>::allocData(u32 num) {
    if (this->mpData != nullptr) {
        delete[] this->mpData;
        this->mpData = nullptr;
    }
    this->mDataNum = 0;
    if (num == 0) {
        return;
    }
    this->mpData = new (16u) T[num];
    this->mDataNum = num;
}

template <typename T>
void rTbl2<T>::deleteData() {
    if (this->mpData != nullptr) {
        delete[] this->mpData;
        this->mpData = nullptr;
    }
    this->mDataNum = 0;
}

